export type BuildingContentLang = 'zh' | 'ja' | 'en'

export interface BuildingContentSection {
  title: Record<BuildingContentLang, string>
  paragraphs: Record<BuildingContentLang, string[]>
}

export interface BuildingContentSource {
  title: string
  url: string
}

export interface BuildingContentOverlay {
  slug: string
  summary: Record<BuildingContentLang, string>
  significance: Record<BuildingContentLang, string>
  sections: BuildingContentSection[]
  sources: BuildingContentSource[]
}

type StudyText = {
  summary: { zh: string; ja: string }
  significance: { zh: string; ja: string }
  context: { zh: string; ja: string }
  design: { zh: string; ja: string }
  reading: { zh: string; ja: string }
  sources: BuildingContentSource[]
}

function enFallback(text: string) {
  return text
}

function study(slug: string, text: StudyText): BuildingContentOverlay {
  return {
    slug,
    summary: { zh: text.summary.zh, ja: text.summary.ja, en: enFallback(text.summary.zh) },
    significance: { zh: text.significance.zh, ja: text.significance.ja, en: enFallback(text.significance.zh) },
    sections: [
      {
        title: { zh: '时代与委托背景', ja: '時代と委託の背景', en: 'Context and commission' },
        paragraphs: { zh: [text.context.zh], ja: [text.context.ja], en: [enFallback(text.context.zh)] },
      },
      {
        title: { zh: '设计思想与空间组织', ja: '設計思想と空間構成', en: 'Design idea and spatial organization' },
        paragraphs: { zh: [text.design.zh], ja: [text.design.ja], en: [enFallback(text.design.zh)] },
      },
      {
        title: { zh: '材料、光线与历史影响', ja: '素材・光・歴史的影響', en: 'Material, light, and historical impact' },
        paragraphs: { zh: [text.reading.zh], ja: [text.reading.ja], en: [enFallback(text.reading.zh)] },
      },
    ],
    sources: text.sources,
  }
}

const wikidata = (id: string): BuildingContentSource => ({ title: `Wikidata ${id}`, url: `https://www.wikidata.org/wiki/${id}` })
const wiki = (title: string, url: string): BuildingContentSource => ({ title, url })

