      ja: 'グラン・ルーヴル計画は、入口の混乱、展示館の分散、来館者増加を解決する必要があった。ペイは非常に敏感な歴史的中庭に向き合い、新しい入口を明快に見せながら、透明で抑制されたものにする必要があった。',
