      ja: 'フィレンツェ大聖堂のドームは、ブルネレスキが工学、幾何、都市的象徴を結びつけた画期的な建築である。伝統的な全面足場なしに巨大な八角形のドラムを覆い、初期ルネサンスの技術的想像力を代表するイメージとなった。',
