      ja: 'フィレンツェ大聖堂は、巨大な開口を覆う実行可能なドーム案を長く欠いていた。共和国都市の競争、宗教儀礼、職人技術が重なり、ブルネレスキは施工可能性と象徴性を兼ねた構造戦略を提案した。',
