      ja: '立面は等間隔の円弧アーチと細い柱で構成され、アーケードは街路と内部施設をつなぎながら保護する緩衝空間になる。比例の制御により、公共建築は重い記念碑性に頼らず、静かで秩序ある表情を得ている。',
