      ja: '立面はローマ円形闘技場を思わせる階層的オーダーで構成されるが、平らな街路壁へ圧縮されている。石材のグリッド、二連窓、コーニスは、住宅を街路スケールで安定し、抑制され、権威あるものにする。',
