      ja: 'サン・カルロ・アッレ・クアットロ・フォンターネは、ボッロミーニが極小敷地で完成させたバロック空間の実験である。波打つ立面、楕円的平面、連続する曲面により、小さな教会は尺度を超える動的緊張を得た。',
