export const buildingContentOverlays: Record<string, BuildingContentOverlay> = {
  ...overlays,
  ...moreOverlays,
  ...finalOverlays,
  ...canonicalOverlays,
  ...landmarkOverlays,
  ...civicOverlays,
  ...contemporaryCivicOverlays,
  ...cultureUrbanOverlays,
  ...modernUrbanOverlays,
  ...heritageModernOverlays,
  ...contemporaryMuseumOverlays,
  ...canonicalModernLineageOverlays,
  ...renaissanceBaroqueOverlays,
  ...renaissanceBaroqueLineageOverlays,
}

export function getBuildingContent(slug: string): BuildingContentOverlay | null {
  return buildingContentOverlays[slug] || null
}

export function localizedBuildingContent<T>(value: Record<BuildingContentLang, T>, lang: string): T {
  if (lang === 'ja') return value.ja
  if (lang === 'en') return value.en
  return value.zh
}
